   303  /*
   304   * It parse a JSON string and convert it to MessagePack format. The main
   305   * difference of this function and the previous flb_pack_json() is that it
   306   * keeps a parser and tokens state, allowing to process big messages and
   307   * resume the parsing process instead of start from zero.
   308   */
   309  int flb_pack_json_state(const char *js, size_t len,
   310                          char **buffer, int *size,
   311                          struct flb_pack_state *state)
   312  {
   313      int ret;
   314      int out;
   315      int delim = 0;
   316      int last =  0;
   317      char *buf;
   318      jsmntok_t *t;
   319
   320      ret = flb_json_tokenise(js, len, state);
   321      state->multiple = FLB_TRUE;
   322      if (ret == FLB_ERR_JSON_PART && state->multiple == FLB_TRUE) {
   323          /*
   324           * If the caller enabled 'multiple' flag, it means that the incoming
   325           * JSON message may have multiple messages concatenated and likely
   326           * the last one is only incomplete.
   327           *
   328           * The following routine aims to determinate how many JSON messages
   329           * are OK in the array of tokens, if any, process them and adjust
   330           * the JSMN context/buffers.
   331           */
   332          int i;
   333          int found = 0;
   334
   335          for (i = 1; i < state->tokens_size; i++) {
   336              t = &state->tokens[i];
   337
   338              if (t->start < (state->tokens[i - 1]).start) {
   339                  break;
   340              }
   341
   342              if (t->parent == -1 && (t->end != 0)) {
   343                  found++;
   344                  delim = i;
   345              }
   346
   347          }
   348
   349          if (found > 0) {
   350              state->tokens_count += delim;
   351          }
   352          else {
   353              return ret;
   354          }
   355      }
   356      else if (ret != 0) {
   357          return ret;
   358      }
   359
   360      if (state->tokens_count == 0) {
   361          state->last_byte = last;
   362          return FLB_ERR_JSON_INVAL;
   363      }
   364
   365      buf = tokens_to_msgpack(state, js, &out, &last);
   366      if (!buf) {
   367          return -1;
   368      }
   369
   370      *size = out;
   371      *buffer = buf;
   372      state->last_byte = last;
   373
   374      return 0;
   375  }
