   377  static int pack_print_fluent_record(size_t cnt, msgpack_unpacked result)
   378  {
   379      msgpack_object o;
   380      msgpack_object *obj;
   381      msgpack_object root;
   382      struct flb_time tms;
   383
   384      root = result.data;
   385      if (root.type != MSGPACK_OBJECT_ARRAY) {
   386          return -1;
   387      }
   388
   389      /* decode expected timestamp only (integer, float or ext) */
   390      o = root.via.array.ptr[0];
   391      if (o.type != MSGPACK_OBJECT_POSITIVE_INTEGER &&
   392          o.type != MSGPACK_OBJECT_FLOAT &&
   393          o.type != MSGPACK_OBJECT_EXT) {
   394          return -1;
   395      }
   396
   397      /* This is a Fluent Bit record, just do the proper unpacking/printing */
   398      flb_time_pop_from_msgpack(&tms, &result, &obj);
   399
   400      fprintf(stdout, "[%zd] [%"PRIu32".%09lu, ", cnt,
   401              (uint32_t) tms.tm.tv_sec, tms.tm.tv_nsec);
   402      msgpack_object_print(stdout, *obj);
   403      fprintf(stdout, "]\n");
   404
   405      return 0;
   406  }
