   408  void flb_pack_print(const char *data, size_t bytes)
   409  {
   410      int ret;
   411      msgpack_unpacked result;
   412      size_t off = 0, cnt = 0;
   413
   414      msgpack_unpacked_init(&result);
   415      while (msgpack_unpack_next(&result, data, bytes, &off) == MSGPACK_UNPACK_SUCCESS) {
   416          /* Check if we are processing an internal Fluent Bit record */
   417          ret = pack_print_fluent_record(cnt, result);
   418          if (ret == 0) {
   419              continue;
   420          }
   421
   422          printf("[%zd] ", cnt++);
   423          msgpack_object_print(stdout, result.data);
   424          printf("\n");
   425      }
   426      msgpack_unpacked_destroy(&result);
   427  }
