   430  static inline int try_to_write(char *buf, int *off, size_t left,
   431                                 const char *str, size_t str_len)
   432  {
   433      if (str_len <= 0){
   434          str_len = strlen(str);
   435      }
   436      if (left <= *off+str_len) {
   437          return FLB_FALSE;
   438      }
   439      memcpy(buf+*off, str, str_len);
   440      *off += str_len;
   441      return FLB_TRUE;
   442  }
